{
  "commands": [
    {
      "name": "complete-asan-configure",
      "argv": [
        "/workspace/.cloud-setup/venv/lib/python3.12/site-packages/cmake/data/bin/cmake",
        "-S",
        "/workspace/dwqww",
        "-B",
        "/workspace/forge-sol-nnue-speed-audit-20261024/build-complete-asan",
        "-DCMAKE_BUILD_TYPE=RelWithDebInfo",
        "-DCMAKE_CXX_EXTENSIONS=OFF",
        "-DCMAKE_CXX_FLAGS=-DFORGE_NNUE_HIDDEN=256 -DFORGE_COMPLETE_ITERATION_ONLY=1 -ffp-contract=off -fno-fast-math -march=znver5",
        "-DCMAKE_CXX_FLAGS_RELWITHDEBINFO=-O1 -g1 -DNDEBUG",
        "-DFORGE_ENABLE_SANITIZERS=ON"
      ]
    },
    {
      "name": "complete-asan-build",
      "argv": [
        "/workspace/.cloud-setup/venv/lib/python3.12/site-packages/cmake/data/bin/cmake",
        "--build",
        "/workspace/forge-sol-nnue-speed-audit-20261024/build-complete-asan",
        "--target",
        "forge",
        "--parallel",
        "2"
      ]
    },
    {
      "name": "complete-asan-smoke",
      "argv": [
        "python3",
        "-B",
        "tools/nnue_asan_smoke.py",
        "/workspace/forge-sol-nnue-speed-audit-20261024/build-complete-asan/forge",
        "--out",
        "/workspace/forge-sol-nnue-speed-audit-20261024/complete-asan-smoke"
      ],
      "environment": {
        "ASAN_OPTIONS": "detect_leaks=1:abort_on_error=1",
        "UBSAN_OPTIONS": "halt_on_error=1:print_stacktrace=1"
      }
    }
  ]
}

